<?php
declare(strict_types=1); namespace App\Controller; use Symfony\Bundle\FrameworkBundle\Controller\AbstractController; use Symfony\Component\HttpFoundation\Response; use Symfony\Component\Routing\Attribute\Route; use Symfony\Component\Security\Http\Authentication\AuthenticationUtils;
final class SecurityController extends AbstractController { #[Route('/login',name:'app_login')] public function login(AuthenticationUtils $a):Response{return $this->render('security/login.html.twig',['last_username'=>$a->getLastUsername(),'error'=>$a->getLastAuthenticationError()]);} #[Route('/logout',name:'app_logout')] public function logout():never{throw new \LogicException('Handled by the firewall.');} }
